TP.register({id:"lp10-g1",lp:10,grade:"1",mode:"curriculum",checks:9,nextGrade:"2nd grade",build(E){const F=E.F;const CAKE="cake",BALLOON="balloons",FLAG="flag",HORN="horn",STAR="star",BALL="soccerBall",BOOK="books",PENCIL="pencil",PALETTE="palette",TREE="tree",SUNFLOWER="sunflower",BUTTERFLY="butterfly",BIRD="bluebird",SUN="sun",BOX="box",EAR="ear",RAINBOW="rainbow",HAT="topHat",MAP="map",FLOWER="purpleFlower",RUN="run";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",PINK="#F4899E",GOLDL="#FBD873",SKYB="#9FD6F0",MINT="#B8E3A8",LILAC="#C9A6EC",CREAM="#FBF1E4",SKY="#D9EEF7",GRASS="#CBE8B0",GRASS_LN="#A0CC84";const PARTY=[PINK,GOLDL,SKYB,MINT,LILAC];function candleShape(x,y,s,c){const k=s/26;return`<g transform="translate(${n1(x)} ${n1(y+2*k)}) scale(${n1(k)})">${candleArt(c)}</g>`}function candleArt(c){return`<image href="data:image/webp;base64,${window.TP_CANDLE}" x="-9.3" y="-33" width="18.6" height="62"/>`}const candleSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*2.3)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a candle">${candleShape(w*.5,w*1.15,w*.86,c)}</svg>`;function balloonShape(x,y,s,c,noString){const k=s/44,c0=c||PINK;return`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">`+(noString?"":`<path d="M0 26 C7 31 -7 35 0 40 C6 44 1 46 4 48" fill="none" stroke="#8A7A6A" stroke-width="2.6" stroke-linecap="round"/>`)+`<ellipse cx="0" cy="-2" rx="22" ry="21" fill="${c0}" stroke="${INK}" stroke-width="2.8"/><path d="M-7 15 H7 L0 28 Z" fill="${c0}" stroke="${INK}" stroke-width="2.8" stroke-linejoin="round"/><ellipse cx="0" cy="-2" rx="22" ry="21" fill="${c0}" stroke="none"/><path d="M-7 15 H7 L0 28 Z" fill="${c0}" stroke="none"/>`+at(0,-3,.5,K_FACE(0,0,12,4))+`</g>`}const balloonSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.6)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a balloon">${balloonShape(w*.5,w*.62,w*.9,c)}</svg>`;const LAST_DAY="Today is the last day of school. Our class set up a long table. It stood out in the yard. We put out everything. We made it all this year. I brought my clay bird. Dev brought a tower of blocks. It is taller than he is. At ten the band began to play. We all sang the song we learned in the winter. Then we walked people out. They came to see the garden. We planted it in the fall. The sunflowers are taller than the fence.";const ROSA="Rosa made a long paper chain for the last day of school. She wanted to hang it across the whole yard. But the chain kept slipping off the hook at the far end, and it would not stay up. Omar ran over with a roll of tape. He climbed two steps up the ladder and taped the chain tight. Rosa held the bottom so it would not twist. When they were done, the chain swung over the tables. It looked like a bridge of color.";const HORN_TEXT="When you blow into a horn, the air inside starts to shake very fast. Shaking air is what sound is. A horn is shaped like a cone. It is narrow where you blow and wide at the other end. The wide end pushes the shaking air out toward the crowd. A longer horn makes a lower sound. That is why the big horns in a band sound deep, and the little ones sound high.";const CAPSULE="Some classes finish the year by making a time capsule. They put small things into a strong box: a photo of the whole class, a list of the songs they sang, a drawing from each child, and a letter to whoever opens it. Then they seal the box and hide it, sometimes in a closet and sometimes under a tree in the yard. A note on the lid says the year it should be opened. When that year comes around, a whole new class lifts the lid and finds out what school was like before they ever got there.";const CREW="The setup crew works before anyone else arrives. They carry the long tables out of the hall, line them up end to end, and clip a strip of bunting along the front of each one. One worker checks that every card sits beside the right thing, because a card in the wrong place sends people to the wrong table. The whole job takes about an hour.";const WORDS=["chop","sing","cream","puff","vote","right","spray","corn","packed","sunshine","garden","vope"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}const skyBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;const frame=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||22}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}function buntingRow(n){const w=620,h=150,x0=40,x1=w-40,drop=26;const mx=(x0+x1)/2,my=54+drop*2;const atT=t=>[(1-t)*(1-t)*x0+2*t*(1-t)*mx+t*t*x1,(1-t)*(1-t)*54+2*t*(1-t)*my+t*t*54];let b=skyBox(w,h);b+=`<path d="M${x0} 54 Q${mx} ${my} ${x1} 54" fill="none" stroke="${INK}" stroke-width="4" stroke-linecap="round"/>`;for(let k=0;k<n;k++){const p=atT((k+.5)/n);b+=`<path d="M${n1(p[0]-15)} ${n1(p[1])} h30 l-15 36 Z" fill="${PARTY[k%5]}" stroke="${INK}" stroke-width="3" stroke-linejoin="round"/>`}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A string of bunting across the yard with ${n} flags hanging from it">${b}</svg>`}function unitFig(){const u=52,y1=58,y2=160,W=460;let s=`<svg viewBox="0 0 ${W} 230" width="440" role="img" aria-label="A bunting string above seven blocks laid end to end, and a ribbon above four blocks laid end to end.">`;s+=frame(W,224);s+=`<path d="M40 ${y1-10} h${7*u}" stroke="${INK}" stroke-width="5" stroke-linecap="round" fill="none"/>`;for(let i=0;i<7;i++)s+=`<path d="M${40+i*u+10} ${y1-10} h${u-20} l${-(u-20)/2} 20 Z" fill="${PARTY[i%5]}" stroke="${INK}" stroke-width="2.4" stroke-linejoin="round"/>`;for(let i=0;i<7;i++)s+=`<rect x="${40+i*u}" y="${y1+22}" width="${u}" height="26" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(40+7*u/2,y1+74,"bunting string",22);s+=`<path d="M40 ${y2-10} h${4*u}" stroke="${PINK}" stroke-width="12" stroke-linecap="round" fill="none"/>`;for(let i=0;i<4;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="26" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(40+4*u/2,y2+50,"ribbon",22);s+=`<text x="${W-20}" y="26" font-size="19" text-anchor="end" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}const CLOCKS=[["A",9,0],["B",2,30],["C",11,30],["D",6,0]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],200)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}function showList(){return F.table(["What we take out","What it is for"],[[`${ic(BOOK,30)} a book of name cards`,"to tell people what each thing is"],[`${ic(PENCIL,30)} a pencil`,"to write one more name card"],[`${ic(FLAG,30)} a flag`,"to put up on the gate"],[`${ic(BALLOON,30)} a balloon`,"to tie on the first chair"]],{caption:"Show Setup List"})}function candleCount(n,per){const cell=72,rowH=100,rows=Math.ceil(n/per),w=24+per*cell,h=14+rows*rowH;let b=frame(w,h);for(let i=0;i<n;i++)b+=candleShape(12+i%per*cell+cell/2,7+Math.floor(i/per)*rowH+rowH/2,44,PARTY[i%5]);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,640)}" role="img" aria-label="${n} candles laid out in rows of ${per}">${b}</svg>`}function shareFig(){const w=700,h=226,st=`stroke="${INK}" stroke-width="3.4"`;let b=frame(w,h);b+=`<circle cx="112" cy="98" r="62" fill="${GOLDL}" ${st}/>`;b+=`<path d="M112 36 V160" fill="none" ${st}/>`;b+=lab(112,196,"A  the round cake",20);b+=`<rect x="232" y="50" width="216" height="96" fill="${SKYB}" ${st}/>`;b+=`<path d="M286 50 V146 M340 50 V146 M394 50 V146" fill="none" ${st}/>`;b+=lab(340,196,"B  the long banner",20);b+=`<rect x="488" y="50" width="192" height="96" fill="${MINT}" ${st}/>`;b+=`<path d="M546 50 V146" fill="none" ${st}/>`;b+=lab(584,196,"C  the short banner",20);return`<svg viewBox="0 0 ${w} ${h}" width="680" role="img" aria-label="Shape A is a round cake with one straight cut down the middle, making two pieces the same size. Shape B is a long banner with three cuts across it, making four pieces the same size. Shape C is a shorter banner with one cut, making a small piece on the left and a much larger piece on the right.">${b}</svg>`}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const DISP="font-family:var(--font-display);font-weight:800";const STOPS=[{id:1,title:"Last Day Sound Check",short:"Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${ic(HORN,96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,qs:["Blend these sounds: /f/ /l/ /a/ /g/","Blend these sounds: /ch/ /air/","Clap the word parts in confetti. How many parts?","What is the last sound in band?","Say all the sounds in cake.","Which word has a short vowel sound: cap or cape?"],key:["flag","chair","3 parts: con-fet-ti","/d/","/k/ /ay/ /k/, three sounds","cap. The final e in cape makes the vowel long."],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Show Day Words",short:"Word Cards",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:85,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. vope is a silly word: listen for the long o that the final e makes.","Watch for: ch digraph (chop), ng ending (sing), blend plus a vowel team (cream), double letters (puff), final e (vote), igh (right), three-letter blend plus a vowel team (spray), r-controlled or (corn), the -ed ending said as /t/ (packed), a compound word (sunshine), two syllables with r-controlled ar (garden)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two syllables"}]},{id:3,title:"Spools of Ten",short:"Tens Ones",parts:[{std:["1.NBT.B.2"],n:5,dur:100,dir:"Look at the blocks. Answer out loud.",html:()=>`<p class="small" style="text-align:center">Ribbon comes on spools. A full spool holds 10 ribbons. A long block stands for one spool. It is a full spool of ten. A small cube stands for a ribbon. It is one loose ribbon.</p>`,fig:()=>F.row(F.tens(4,6)),qs:["Look at the picture. How many full spools of ten do you see, and how many loose ribbons? What number is that?","In the number 29, what does the 2 stand for? What does the 9 stand for?","The show needs 70 ribbons. How many full spools of ten is that? How many loose ones are left over?","Which is more, 5 spools of ten or 40 ribbons? How do you know?","The number 23 is two tens and three ones. Say a number that is two tens and eight ones."],key:["4 spools of ten and 6 loose. That is 46","The 2 stands for two tens, which is twenty ribbons. The 9 stands for nine ones","7 spools of ten, and 0 loose ribbons left over","5 spools of ten. 5 tens is 50, and 50 is more than 40","28"],desc:"place value in two-digit numbers (bundles of ten and leftover ones)"}]},{id:4,title:"Our Last Day",short:"Read It",parts:[{std:["RF.1.4"],kind:"read",n:82,label:"words read correctly",dur:95,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(BIRD,"the clay bird","3.6rem"),F.pic(HORN,"the band","3.6rem"),F.pic(SUNFLOWER,"the class garden","3.6rem"))}${story("Our Last Day",LAST_DAY)}`,key:["82 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so clay bird, band, and garden are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: How tall are the sunflowers now? (taller than the fence)"],desc:"an 82-word end of year story read aloud"}]},{id:5,title:"Rosa's Paper Chain",short:"Rosa",parts:[{std:["RL.1.1"],dur:95,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("Rosa's Paper Chain",ROSA),qs:["What did Rosa make?","Where did she want to hang it?","What was the problem at the far end?","Who helped Rosa, and how?","Ask me a question about the story."],key:["A long paper chain","Across the whole yard","The chain kept slipping off the hook","Omar. He brought a roll of tape, climbed two steps on the ladder, and taped the chain tight","Asks a real question about the story, such as: What color was the chain? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:6,title:"Add Up the Tables",short:"Add Up",parts:[{std:["1.NBT.C.4"],n:5,dur:95,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="big" style="margin-top:0">The crew counts the chairs table by table.</p>`,qs:["The first table has 34 chairs. The crew adds 5 more. How many now?","The second table has 52 chairs. The crew adds 30 more. How many now?","The third table has 47 chairs. The crew adds 8 more. How many now?","The fourth table has 61 chairs. The crew adds 20 more. How many now?","The back row has 76 chairs. The crew adds 9 more. How many now?"],key:["39 (34 + 5 = 39. Only the ones change)","82 (52 + 30 = 82. Adding tens to tens: 5 tens and 3 tens is 8 tens)","55 (47 + 8 = 55. 7 + 8 is 15, so a new ten is made)","81 (61 + 20 = 81)","85 (76 + 9 = 85. 6 + 9 is 15, so a new ten is made)"],desc:"adding within 100 (a two-digit number plus a one-digit number and plus a multiple of ten)"}]},{id:7,title:"Take Away Tens",short:"Take Tens",parts:[{std:["1.NBT.C.6"],n:5,dur:80,dir:"Answer out loud. For the last one, tell how you know.",html:()=>`<p class="big" style="margin-top:0">Every spool that comes off the rack takes ten ribbons out of the count.</p>`,fig:()=>F.row(F.tens(8,0)),qs:["There are 80 ribbons on the rack. Three spools of ten come off. 80 - 30 is what?","50 - 20","90 - 60","70 - 70","60 - 10. Tell me how you know, using the word tens."],key:["50 (8 tens take away 3 tens is 5 tens)","30","30","0","50. Looks for: 6 tens take away 1 ten is 5 tens, which is 50"],desc:"subtracting multiples of ten from multiples of ten within 100"}]},{id:8,title:"Measure the Bunting",short:"Measure",parts:[{std:["1.MD.A.2"],n:5,dur:105,dir:"Look at the blocks under the bunting string and the ribbon. Answer out loud.",fig:()=>F.row(unitFig()),qs:["How many blocks long is the bunting string?","How many blocks long is the ribbon?","Which is longer, the bunting string or the ribbon? How many blocks longer?","Why do the blocks have to touch, with no gaps and no overlaps?","If you measured the bunting string with blocks that were half as long, would you need more blocks or fewer blocks?"],key:["7 blocks","4 blocks","The bunting string. It is 3 blocks longer (7 - 4 = 3)","A gap or an overlap would make the count wrong. The blocks have to sit end to end so each one covers its own part of the length","More blocks. Smaller units means it takes more of them to cover the same length"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:9,title:"The Clock in the Hall",short:"Clocks",parts:[{title:"Read the Clock",std:["1.MD.B.3"],n:4,dur:100,dir:"Look at each clock. Say the time out loud.",desc:"telling time on an analog clock to the hour and the half hour",html:()=>`<p class="big" style="margin-top:0">The clock in the hall keeps the whole show on time.</p>`,fig:()=>clockRow(),key:["Clock A: 9:00, said as nine o'clock. The minute hand points straight up at the 12.","Clock B: 2:30, said as two thirty or half past two. Watch for a student who says three thirty because the hour hand has moved halfway to the 3.","Clock C: 11:30, said as eleven thirty or half past eleven. The hour hand sits between the 11 and the 12.","Clock D: 6:00, said as six o'clock. Both hands are in a straight line, which trips some students up."]},{title:"Write the Time",std:["1.MD.B.3"],n:5,dur:85,dir:"Write each answer on your paper and hold it up.",desc:"writing times to the hour and the half hour and reading a digital clock",fig:()=>F.row([F.digital("1:30"),"The digital clock by the door"],[F.clock(4,0,200),"The hall clock later on"]),qs:["Look at the digital clock. Write that time.","Look at the hall clock. Write that time.","Write half past seven using numbers.","Write eight o'clock using numbers.","A clock says 3:30. Where is the hour hand pointing?"],key:["1:30","4:00","7:30","8:00","Halfway between the 3 and the 4, not right on the 3"]}]},{id:10,title:"How a Horn Makes Sound",short:"Horns",parts:[{title:"Listen to the Facts",std:["RI.1.1"],n:3,dur:70,dir:"Read the facts out loud. Then answer out loud.",desc:"answering key detail questions about an informational text the student read",html:()=>`<div class="figure" aria-hidden="true">${ic(HORN,80)}${ic(EAR,64)}</div><p class="passage">${HORN_TEXT}</p>`,qs:["What starts to shake when you blow into a horn?","What is sound?","What shape is a horn?"],key:["The air inside it","Shaking air","A cone, narrow where you blow and wide at the other end"]},{title:"Your Turn",std:["RI.1.1"],n:3,dur:80,dir:"Use the facts to answer. Then ask your teacher a question.",desc:"answering why questions from an informational text and asking a question about it",html:()=>`<details class="look-back" open style="margin-bottom:10px"><summary>How a Horn Makes Sound (click to open or close)</summary><p class="passage">${HORN_TEXT}</p></details>`,qs:["Which horn makes a lower sound, a long one or a short one?","Why do the big horns in a band sound deep?","Ask me a question about horns or about sound."],key:["A long one","Because a longer horn makes a lower sound, and the big horns are the long ones","Asks a real question that fits the topic, such as: How do you make a horn louder?"]}]},{id:11,title:"Program Check",short:"Program",parts:[{title:"Sentence Spotter",std:["RF.1.1"],n:4,dur:50,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The yard is full. Can you hear the band?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the band starts at two</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Fix It",std:["L.1.1"],n:6,dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today we clap. Last week we ____.","One child, two ____.","Which sounds right? The balloons floats over the yard. Or: The balloons float over the yard.","Join these two sentences with the word <b>but</b>: The music was loud. We sang anyway.","Add a word that tells more about the chain: The ____ chain swung over the tables.","Finish it so it tells where: The ball rolled ____ the table."],key:["clapped","children","The second one. More than one balloon goes with the verb float","The music was loud, but we sang anyway","Any describing word that fits, such as long, paper, bright, or colorful","Any word that tells where and fits, such as under, past, behind, or beside"],desc:"spoken grammar items (past tense, irregular plural, subject and verb match, joining two sentences, describing words, place words)"}]},{id:12,title:"Show Day Talk",short:"Talk",parts:[{std:["L.1.1"],n:4,dur:60,dir:"Listen to your teacher. Say your answer out loud.",html:()=>`<div class="figure">${balloonSvg(64,SKYB)}${ic(PALETTE,56)}${candleSvg(34,GOLDL)}</div>`,qs:["Fix this sentence: Yesterday I bring my painting to school.","One box, two ____.","Join these two sentences with the word <b>because</b>: We clapped for a long time. The song was so good.","Which word fits? The band played ____. Is it loud or loudly?"],key:["Yesterday I brought my painting to school","boxes","We clapped for a long time because the song was so good","loudly. It tells how the band played"],desc:"spoken grammar items (irregular past tense, plural with -es, joining sentences with because, adverbs)"}]},{id:13,title:"Time Capsule Radio",short:"Listen",parts:[{title:"Listen Up",std:["SL.1.2"],n:4,dur:75,read:CAPSULE,dir:"Listen carefully. Your teacher will read about something classes do at the end of the year. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What is a time capsule? (a strong box packed with small things from this year, sealed up and put away to be opened later)","Ask: Name two things that go inside it. (any two: a photo of the whole class, a list of the songs they sang, a drawing from each child, a letter to whoever opens it)","Ask: Where do classes hide it? (in a closet, or under a tree in the yard)","Say: Ask me one question about time capsules. (asks 1 question that is about what was read and starts with a question word, such as: How long do they wait before they open it?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about one thing you made or learned this year.</p><ul class="qlist" style="margin-top:14px"><li>What is it?</li><li>What did it take to make it or to learn it?</li><li>How do you feel about it now?</li></ul>`,key:["Names the thing they made or learned and gives 2 or more details about it (SL.1.4)","Says what it took, with 2 or more details, all about this one thing (SL.1.4)","Says how they feel about it now, in at least 1 complete sentence (SL.1.4)"],desc:"describing a thing with relevant details"}]},{id:14,title:"Use the Show List",short:"Show List",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:90,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">People keep asking what each thing on the table is. What should the class take out so people can tell? Use the chart.</p>`,fig:()=>showList(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the row headings","Writes a sentence drawn from the chart, such as: They should take out the book of name cards","The answer fits the question. It names the one row of the chart whose purpose is telling people what each thing is"],desc:"using a provided chart to answer a question in writing"}]},{id:15,title:"Year End Journal",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Show or Watch",icon:"💬",hint:"Tell what you think and why"},std:["W.1.1"],n:4,label:"checks met",dur:175,dir:WDIR,html:()=>`<p class="big">At the show, would you rather stand by your own table and show people what you made, or walk around and look at what everybody else made? Write what you think and tell why.</p><div class="figure">${F.pic(PALETTE,"show what you made","3.6rem")}${F.pic(RUN,"walk around and look","3.6rem")}</div>${TWO}`,key:["Names the topic: showing your own work or walking around to see everyone else's (W.1.1)","States an opinion, which one the student would pick (W.1.1)","Gives at least one reason for the opinion, such as you get to talk about it or you see more (W.1.1)","Gives some sense of closure, such as: That is why I would pick it (W.1.1)"],desc:"an opinion piece about showing your own work or looking at everyone else's"},{wk:"story",alt:{group:"story",label:"A Last Day I Remember",icon:"✏",hint:"Tell two things that happened, in order"},std:["W.1.3"],n:4,label:"checks met",dur:175,dir:WDIR,html:()=>`<p class="big">Write about the last day of something you remember: the last day of a class, a trip, or a visit. Tell two things that happened, in order. Use the words first and then. End by telling how it felt.</p><div class="figure">${F.pic(CAKE,"the last day","3.4rem")}${F.pic(BALL,"what happened","3.4rem")}${F.pic(STAR,"how it felt","3.4rem")}</div>${TWO}`,key:["Tells about two or more things that happened, in an order that makes sense (W.1.3)","Includes some detail about what happened, not just a list (W.1.3)","Uses a time word such as first, then, next, or after that to signal the order (W.1.3)","Ends with a sense of closure, such as how it felt or what happened last (W.1.3)"],desc:"a narrative about the last day of something the student remembers"}]},{id:16,title:"Read the Banners",short:"Banners",parts:[{std:["RF.1.3"],n:3,dur:55,dir:"Read each banner out loud. Sound out any word that is tricky.",desc:"applying phonics and word-analysis skills to decode words inside sentences",html:()=>`<div style="display:grid;gap:14px;justify-content:center;margin:8px 0">${["The bright banners hang over the yard.","We packed the drums into a green crate.","Each child brought one thing to show."].map(t=>`<div style="border:4px solid var(--gold-ink);border-radius:16px;background:var(--surface);padding:12px 26px;${DISP};font-size:clamp(1.4rem,4vw,2.1rem);text-align:center">${t}</div>`).join("")}</div>`,key:["Banner 1: listen for igh in bright, the two syllables in banners, and the r-controlled ar in yard.","Banner 2: listen for the -ed ending said as /t/ in packed, the ea team in each, and the final e making a long a in crate.","Banner 3: listen for the ch digraph in each and child, and for brought, which has to be known by sight.","Score is the number of banners read with every word right. A word the student fixes alone still counts."]}]},{id:17,title:"Numbers on the Rack",short:"Numbers",parts:[{title:"Count and Write",std:["1.NBT.A.1"],n:3,dur:60,dir:"Count out loud. Then write the number on your paper.",desc:"counting past 100 from a given number, counting a set, and writing numerals to 120",fig:()=>F.row(candleCount(23,8)),qs:["Start at 96 and count out loud up to 112.","Count the candles on your screen, then write that number on your paper and hold it up.","Write the number one hundred eight on your paper."],key:["Say: Start at 96 and count out loud up to 112. (96, 97, 98, 99, 100, 101 and on to 112. The usual slip is 99 to 200 or 100 to 200. Write down where it broke.)","Say: Count the candles on your screen, then write that number on your paper and hold it up. (23. The picture holds 23 candles, in rows of 8, 8 and 7.)","Say: Write the number one hundred eight on your paper. (108. Watch for 1008, which comes from writing what you hear.)"]},{title:"Count On, Count Back",std:["1.OA.C.5"],n:3,dur:45,dir:"Answer out loud. Say the numbers you count.",desc:"adding and subtracting by counting on and counting back from a given number",html:()=>`<div class="figure">${balloonSvg(60,PINK)}${candleSvg(32,SKYB)}</div><p class="big" style="text-align:center">Do not start over at one. Start at the number you are given.</p>`,qs:["There are 12 balloons tied on the chairs. The crew ties on 3 more. Count on from 12 to find how many.","There are 15 candles on the table. Two get carried away. Count back to find how many are left.","For 9 plus 2, is it quicker to count on from 9 or to count everything from 1? Why?"],key:["Say: There are 12 balloons tied on the chairs. The crew ties on 3 more. Count on from 12 to find how many. (13, 14, 15, so 15. Listen for the count starting at 13, not at 1.)","Say: There are 15 candles on the table. Two get carried away. Count back to find how many are left. (14, 13, so 13.)","Say: For 9 plus 2, is it quicker to count on from 9 or to count everything from 1? Why? (Counting on from 9, because you only say two more numbers instead of saying all of them from the start.)"]}]},{id:18,title:"Problems at the Show",short:"Problems",parts:[{title:"Word Problems",std:["1.OA.A.1"],n:3,dur:60,dir:"Solve each one on your paper. You can draw. Say your answer out loud.",desc:"addition and subtraction word problems within 20, with the unknown in different places",html:()=>`<div class="figure">${ic(HORN,54)}${ic(BALL,54)}${ic(BOOK,54)}</div>`,qs:["The band has 8 horns and 7 drums. How many instruments is that in all?","There were 14 chairs in the front row. Some were carried away, and 9 chairs were left. How many were carried away?","Dev has 6 name cards. Rosa has 13. How many more name cards does Rosa have than Dev?"],key:["Say: The band has 8 horns and 7 drums. How many instruments is that in all? (15. 8 + 7 = 15. Putting together.)","Say: There were 14 chairs in the front row. Some were carried away, and 9 chairs were left. How many were carried away? (5. 14 - 9 = 5, or 9 + 5 = 14. The unknown is the change, which is harder than a plain take away.)","Say: Dev has 6 name cards. Rosa has 13. How many more name cards does Rosa have than Dev? (7. 13 - 6 = 7. Comparing.)","A drawing, counters or an equation all count as showing the work. Write down which problem type gave trouble, since the second and third are the ones that usually do."]},{title:"Another Way to Add",std:["1.OA.B.3"],n:3,dur:45,dir:"Answer out loud. Tell how you know.",desc:"using the order of addends and making a ten as strategies for adding",html:()=>`<p class="big" style="text-align:center">You can move the numbers around to make adding easier.</p>`,qs:["You already know that 9 plus 4 is 13. So what is 4 plus 9? How do you know without adding it?","Add 7 plus 3 plus 6. Which two would you add first, and why?","Is 5 plus 8 the same as 8 plus 5? What is the answer?"],key:["Say: You already know that 9 plus 4 is 13. So what is 4 plus 9? How do you know without adding it? (13. The same two numbers added in the other order give the same total.)","Say: Add 7 plus 3 plus 6. Which two would you add first, and why? (7 and 3 first, because they make 10, and then 10 plus 6 is 16. The answer is 16.)","Say: Is 5 plus 8 the same as 8 plus 5? What is the answer? (Yes, both are 13. Order does not change the total.)","The reason matters more than the number here. An answer with no reason is partly there."]}]},{id:19,title:"What the Class Brought",short:"Graph",parts:[{std:["1.MD.C.4"],n:3,dur:50,dir:"Look at the graph. Answer out loud.",desc:"reading a graph with three categories: each category, the total, and how many more",fig:()=>F.row(F.barGraph({title:"What we brought to the show",cats:["Paintings","Towers","Plants"],vals:[8,5,6],max:10,step:1})),qs:["How many children brought a painting?","How many children are on this graph in all?","How many more children brought a painting than a tower?"],key:["Say: How many children brought a painting? (8)","Say: How many children are on this graph in all? (19. 8 + 5 + 6 = 19.)","Say: How many more children brought a painting than a tower? (3. 8 - 5 = 3.)","The three bars are Paintings 8, Towers 5, Plants 6. If a bar is read off by one, check whether the student lined the top of the bar up with the number scale on the left."]}]},{id:20,title:"Cut It Into Fair Shares",short:"Shares",parts:[{std:["1.G.A.3"],n:4,dur:55,dir:"Look at the three shapes. Answer out loud.",desc:"halves and fourths of circles and rectangles, and why more shares makes each share smaller",fig:()=>F.row(shareFig()),qs:["Shape A is the round cake, cut into 2 pieces the same size. What do we call one of those pieces?","Shape B is the long banner, cut into 4 pieces the same size. What do we call one piece? And what is the whole banner?","Look at shape C. Is it cut into halves? How do you know?","Which is bigger, a half of the cake or a fourth of the cake? Why?"],key:["Say: Shape A is the round cake, cut into 2 pieces the same size. What do we call one of those pieces? (a half, or one half of the cake)","Say: Shape B is the long banner, cut into 4 pieces the same size. What do we call one piece? And what is the whole banner? (a fourth, or a quarter. The whole banner is four fourths, or all four of the quarters.)","Say: Look at shape C. Is it cut into halves? How do you know? (No. The two pieces are not the same size, and halves have to be equal shares.)","Say: Which is bigger, a half of the cake or a fourth of the cake? Why? (A half. Cutting a whole into more equal shares makes each share smaller.)"]}]},{id:21,title:"Tell About the Show",short:"Facts",parts:[{wk:"facts",std:["W.1.2"],n:4,label:"checks met",dur:70,dir:WDIR,desc:"a short informative piece: names a topic, supplies facts, and closes",html:()=>`<div class="figure">${ic(PENCIL,52)}${ic(FLAG,52)}${ic(SUNFLOWER,52)}</div><p class="big">Pick one part of an end of year show: the tables, the band, the garden, or the name cards. Write what it is and two true things about it. Then write one sentence to finish.</p>${TWO}`,key:["Names the topic in the first sentence, such as: The garden is what our class planted (W.1.2)","Supplies at least two facts about that topic (W.1.2)","Both facts are about the topic named, not about something else at the show (W.1.2)","Ends with a sense of closure, such as: That is why we show it on the last day (W.1.2)","Two or three sentences is enough. This is a short check of the shape of an informative piece, not a full report."]}]},{id:22,title:"Copy a Sunflower Stalk",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job a plant part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A sunflower holds up a heavy head. The head is full of seed. It holds it all summer. Its stalk is thick and rough. It is full of stiff strings. The strings are running up it. They start at the ground. They go to the top. It does not fold over.</p>
     <div class="figure">${ic("sunflower",104)}${ic("sprout",80)}</div>
     <p class="big">The show has a big paper sign. It keeps folding over. It folds in the middle. So nobody can read it.</p>`,qs:["How does a thick stalk with stiff strings running up it hold a heavy flower head up all summer?","Draw a support for the sign that copies the sunflower's stalk.","Tell me which plant part you copied and how your support stops the sign folding."],key:["The stiff strings run the whole way up, so the weight is carried from the top right down to the ground instead of bending in the middle. Any answer about being stiff all the way up counts.","Any stiff support: a batten or stick taped along the back, a pole on each end, a frame round the sign, a stiff board behind it. A single piece of tape in the middle is partial, so ask what the whole stalk does.","Needs both halves: names the thick stiff stalk as the part copied, and says a stiff strip running the whole length keeps the middle from bending."]}]},{id:23,title:"Sheep and Lambs",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"The field beside the school has forty sheep in it and nearly as many lambs. When the farmer moves them to a new field they all mix together. Every ewe calls as she walks, and every lamb calls back. Each ewe knows her own lamb's voice and each lamb knows its own mother's, so after a minute or two every pair has found each other again. Then each lamb walks beside its own mother, and the flock sorts itself out.",qs:["What does every ewe do while she walks to the new field?","What does a lamb do when it hears its own mother's call?","Forty sheep and forty lambs all mix together. How does calling and answering sort them back into pairs?"],key:["She calls. Every ewe, every time, which is what makes it a pattern.","It calls back and goes to her.","Each voice is different, and each one knows the voice of its own pair, so they find each other by sound even in a crowd."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A new strawberry plant that grew off a runner from the parent plant. A young sheep and the sheep that is its parent.</p>
     <div class="figure">${ic("strawberry",88)}${ic("strawberry",112)}</div>
     <div class="figure">${ic("sheep",88)}${ic("sheep",112)}</div>`,qs:["Name one way the new strawberry plant is like the parent plant it grew off.","The new plant is much smaller and has no berries on it yet. Does that mean it is a different kind of plant? Say why.","The young sheep has the same shaped ears, legs and face as its parent, but a shorter coat and a smaller body. Say in your own words how young animals compare to their parents."],key:["Same kind of leaves, same green color, same low spreading shape, both strawberry plants. Any likeness counts.","No. It is the same kind of plant, it is just younger and smaller. Young plants are like their parents without being exactly like them.","They are like their parents but not exactly like them. Listen for both halves of that, not just one."]}]},{id:24,title:"Watching the Moon",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">A class kept a moon log, looking every second night for a week.</p>
     <table class="bigTable"><tr><th>Night</th><th>What the moon looked like</th></tr>
     <tr><td>Monday</td><td>a thin curve</td></tr><tr><td>Wednesday</td><td>a thicker curve</td></tr>
     <tr><td>Friday</td><td>half a circle</td></tr><tr><td>Sunday</td><td>more than half</td></tr></table>
     <div class="figure">${ic("moon",84)}${ic("star",84)}${ic("telescope",84)}</div>`,qs:["Is the lit part of the moon getting bigger or smaller as the week goes on?","What do you predict the moon will look like on the Tuesday after that log ends?","Which part of the log told you that?","The class also saw the moon in the daytime sky one afternoon. Is the moon only there at night, or is it there all the time?"],key:["bigger each time","Bigger again, close to a full round circle.","It grew by about the same amount every second night, all through the log. A thing that changes the same way over and over is a pattern.","It is there all the time. We can see it in the daytime when the sky conditions are right, and it does not stop existing when we cannot see it."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">The class counted the hours of daylight four times across the school year.</p>
     <table class="bigTable"><tr><th>When</th><th>Hours of daylight</th></tr>
     <tr><td>start of school, September</td><td>12</td></tr>
     <tr><td>December</td><td>9</td></tr><tr><td>March</td><td>12</td></tr>
     <tr><td>last day of school, June</td><td>15</td></tr></table>`,qs:["Which time of year on the chart had the fewest hours of daylight?","Two of the four had exactly the same number of hours. Which two?","The class walks home after school. Using the chart, say when they walk home in the dark and when they walk home in bright daylight."],key:["December, 9 hours","September and March, both 12 hours","Darkest in December, when there are only 9 hours of daylight. Brightest in June, with 15 hours, so the walk home on the last day of school is in full daylight."]}]},{id:25,title:"Sound in the Hall",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a paper streamer and a radio, try the second part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Blow a horn once and then press the flat of your hand against the end of it while it is still sounding.</p>
     <div class="figure">${ic("megaphone",96)}${ic("radio",96)}</div>
     <p class="big">Now tape a long paper streamer so the loose end hangs just in front of a speaker, and play a loud drumbeat.</p>`,qs:["While the horn is sounding, what is happening to the air inside it?","You press your hand on the end of the horn. What happens to the sound, and why?","What does the loose end of the paper streamer do while the drumbeat plays?","Nothing touched the streamer. Say what moved it, and how."],key:["It is shaking back and forth very fast. The shaking air is what makes the note.","The note stops or goes dull, because your hand stops the shaking. No shaking, no sound.","It flutters, waves, or jumps in time with the beat.","The speaker shook, the shaking speaker shook the air, and the shaking air moved the streamer. A sound can move a thing without touching it."]}]},{id:26,title:"The Dark Store Room",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The store room is behind the stage. It has no window. The door is closed. The light is off. There is no light in there. There is none at all.</p>
     <div class="figure">${ic("trophy",96)}${ic("torch",96)}</div>`,qs:["The gold trophy for the show is on a shelf in that store room with the door closed. Can you see it? Say why or why not.","What has to reach the trophy before anybody can see it?","Somebody says gold gives off its own light. Is that true of a gold trophy? Say what a shiny gold thing really does with light."],key:["No. No light reaches it, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: the light switched on, a flashlight, or the door opened.","No. Gold does not make light, it bounces light back very well. With no light to bounce, it cannot be seen at all."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One stage lamp beam was pointed at four things and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clear plastic cup</td><td>went straight through</td></tr>
     <tr><td>a paper streamer</td><td>a soft colored light came through</td></tr>
     <tr><td>a cardboard sign</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a shiny foil balloon</td><td>bounced off across the hall</td></tr></table>`,qs:["Which thing made the dark shadow?","Which thing changed the color of the light that came through?","The crew wants a shadow shape on the back wall for one part of the show. Which of the four should they hold up, and why?","They also want to throw a spot of light onto the side wall without moving the lamp. Which one does that, and why?"],key:["the cardboard sign","the paper streamer","the cardboard sign, because it stops the light completely and leaves a dark shape on the wall behind it.","the shiny foil balloon, because it bounces the beam off in a new direction instead of stopping it or letting it through."]}]},{id:27,title:"Backstage to the Booth",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The light booth is at the back. It is at the very back. The hall ends there. The stage is at the front. During the show nobody can call out. The people backstage cannot reach the booth. That is because the audience would hear.</p>
     <div class="figure">${ic("lamp",88)}${ic("board",88)}${ic("star",88)}</div>`,qs:["Draw a device that tells the booth at the back that the next act is ready. It has to use light or sound, and the audience must not notice.","Say what your device is and whether the booth will see it or hear it.","The booth needs to answer back that it is ready too. Say what its answer would be and how backstage will know what it means."],key:["Any quiet light signal or a sound only the booth would hear: a small lamp backstage that the booth can see, a flashlight pointed at the booth, a buzzer with an earpiece, a light that changes color. Something loud enough for the audience does not meet the condition, so ask about that.","Names it and says which one it uses.","An agreed answering signal: one flash back means ready, two flashes mean wait. The agreement is what turns a light into a message."]}]},{id:28,title:"Fix the Tearing Chain",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"The class made a long paper chain to hang across the hall for the show. Every link is a strip of paper glued into a ring. When two people lift the chain up to hang it, a link tears somewhere along the middle nearly every time, and the whole chain comes down.",qs:["What is the problem with the paper chain?","What would you ask the class about the chain before you changed it?","Before you change the chain, what would you look at closely first?"],key:["Links in the paper chain tear when the chain is lifted to be hung up.","Any real question: how long is the chain, how heavy is it, where do the links tear, how wide is a strip, is it the glue or the paper that gives way. A statement is not a question, so ask once more.","Any real observation: count how many links tear, watch where along the chain they tear, see whether the paper rips or the glue comes unstuck, measure how wide the strips are."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw a better link for the chain, or a better way to lift it, so it does not tear.</p>
     <div class="figure">${ic("board",88)}${ic("box",88)}${ic("pencil",88)}</div>`,qs:["Draw your idea on the paper.","Point to the part that takes the pulling and tell me its shape.","Tell me why that shape is stronger than a thin paper ring."],key:["Any real fix: wider strips, a double thickness of paper, links made of card, a string running through all the links, more people lifting along the length, tape across each join.","Names a shape: a wide band, a doubled loop, a straight string through the middle, a thick card ring.","Because a wider or thicker shape spreads the pull over more paper, and a string takes the pull instead of the paper. A thin ring has the whole pull on one narrow strip."]}]},{id:29,title:"Which Link Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two kinds of link were tested, twelve of each, lifted the same way.</p>
     <table class="bigTable"><tr><th>Link</th><th>Links that tore, out of 12</th></tr>
     <tr><td>a wide card ring</td><td>1</td></tr>
     <tr><td>a thin paper ring</td><td>8</td></tr></table>`,qs:["Which link worked better in the test?","Use both numbers from the chart in your answer.","The thin paper rings were prettier. Is that a reason to use them for the chain across the hall? Say what you would do."],key:["the wide card ring","Only 1 of the 12 card rings tore, and 8 of the 12 paper rings tore. The numbers have to be in the answer.","Being prettier is not a test result, so it does not make them stronger. A sensible answer is to use the card rings, or to make card rings and decorate them to look the way they wanted."]}]},{id:30,title:"The Last Day Vote",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and explaining what people owe each other after a vote",read:"The class had time for two songs in the show and four songs had been suggested. Every child wrote one choice on a slip and folded it over. Two children counted the slips in front of everybody and wrote the totals on the board. The two songs with the most slips were chosen. Then the whole class, including the children whose song did not win, practiced the two that did. Nobody sulked and nobody spoiled the practice. Playing fair and taking a loss well like that is called good sportsmanship.",qs:["Every child got a slip and a choice. Is getting a say a right or a responsibility?","Counting the slips in front of everybody is a job. Is that a right or a responsibility, and why does doing it openly matter?","The children whose song did not win practiced anyway. Why is that the right thing to do after a vote?","Nobody sulked or spoiled the practice after the vote. What do we call playing fair and taking a loss well like that, and name one thing a bad sport might have done instead?"],key:["a right","A responsibility. Doing it where everybody can see means everybody can trust the count, and a vote only works if people trust it.","Because the class decided together, and a decision everybody made belongs to everybody. They can ask for their song next time.","Good sportsmanship, or fair play. For the second part, any real example: refusing to practice, sulking, saying the count was wrong without a reason, spoiling the song on purpose, telling the winners their song is bad. Both parts are what is being checked. (HSS-1.1)"]}]},{id:31,title:"The School Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the school grounds, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("cabin",56)}</td><td>${ic("cabin",56)}</td><td>${ic("flag",56)}</td></tr>
     <tr><th>B</th><td></td><td>${ic("soccerBall",56)}</td><td></td></tr>
     <tr><th>C</th><td>${ic("tree",56)}</td><td></td><td>${ic("sprout",56)}</td></tr></table>
     <p class="big">${ic("cabin",48)} the classrooms &nbsp; ${ic("flag",48)} the flagpole &nbsp; ${ic("soccerBall",48)} the playing field &nbsp; ${ic("tree",48)} the old oak &nbsp; ${ic("sprout",48)} the school garden</p>`,qs:["Find the flagpole. Give its exact spot on the grid, the letter and the number.","Where is the school garden compared to the flagpole? Use words like above, below, left of, or right of.","Which thing here grew on its own, and which thing did people put up?","A class walks from a classroom at A1 to the school garden. Name the squares they could cross on the way, moving one square at a time."],key:["A3. Both parts are needed.","Below the flagpole, in the same column.","Needs both halves. Nature: the old oak. Built: the classrooms, the flagpole, the playing field, the school garden.","Any sensible square by square path, for example A1 to B1 to C1 to C2 to C3, or A1 to A2 to B2 to C3. The point is a path that moves square by square."]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">In the show the class sang. They sang two songs. One was in English. One was in another language. Four children speak it at home. The class has twenty three children. Between them they have family far away. It is in twelve different places.</p>
     <div class="figure">${ic("books",88)}${ic("globe",88)}${ic("star",88)}</div>`,qs:["Do all the children in one class have family from the same place? Say how you know from the story.","Name three things at your school that people built, and say what one of them is used for.","Name one good thing about going to school with children whose families come from many different places."],key:["No. Twenty three children have family from twelve different places.","Any three built things with a use for one: a classroom for lessons, a hall for shows, a playing field for games, a library for books, a gate, a path.","Any real answer: you learn new words, you hear new music, you taste new food, you hear about other places, you make friends who know different things."]}]},{id:32,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"recognizing that a national symbol can be a song as well as an object, and naming where symbols appear",html:()=>`<p class="big">The show began one way. Many gatherings in this country begin so. Everybody stands to sing. They sing the national anthem. A country's symbol can be many things. It need not be real. Maybe you cannot hold something. It can be a song. It is one that everyone knows.</p>
     <div class="figure">${ic("flag",96)}${ic("star",96)}</div>`,qs:["Name a symbol of the United States that you can see, and a symbol of the United States that you can hear.","Why does a whole room stand up when the national anthem is played?","Name one place in your own town where you have seen the flag flying."],key:["Needs both halves. Seen: the flag, the bald eagle, the Statue of Liberty. Heard: the national anthem. Accept the Pledge of Allegiance as something said rather than sung.","To show respect for what the song stands for, and because standing together is something people here do as a group. Any answer about respect or doing it together counts.","Any real place: a school, a post office, a fire station, a park, a shop, a sports ground, outside a house."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Taking a picture to remember a school day.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>the camera</td><td>a big box on three wooden legs</td><td>a small camera or a phone</td></tr>
     <tr><td>how long to see it</td><td>days, after it was developed</td><td>straight away on the screen</td></tr>
     <tr><td>why people took it</td><td>to remember the day later</td><td>to remember the day later</td></tr>
     <tr><td>manners at the table</td><td>wait until everyone is served, say please and thank you, ask before leaving the table</td><td>say please and thank you, and in many homes still wait and still ask</td></tr></table>
     <div class="figure">${ic("camera",88)}${ic("phone",88)}</div>`,qs:["Long ago, what did a camera look like?","What do people take pictures with today?","Look at the manners row. Name one table manner that is still the same today, and one that is not always done now.","Point to the row where nothing changed, and say what it is."],key:["A big box standing on three wooden legs.","A small camera or a phone.","Still the same: saying please and thank you. Not always done now: waiting until everyone is served, or asking before leaving the table. Both parts are what is being checked, because manners are one of the things this standard asks you to compare. (HSS-1.4)","Why people took it: to remember the day later. That is the half of the standard that is easy to miss, so it is asked on its own."]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["unpacked","brightly","afternoon"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["unpacked (prefix un-, and the -ed ending said as /t/)","brightly (igh plus the suffix -ly)","afternoon (three syllables, a compound word with the oo team)"]},3:{id:"L3",lv:true,title:"Level Up: Hundreds, Tens, and Ones",std:["2.NBT.A.1"],needs:["1.NBT.B.2"],n:3,dir:"Answer out loud.",html:()=>`<p class="big">Now the ribbons come in cases. One case holds 100.</p><ol class="qlist"><li>In the number 348, what does the 3 stand for? What does the 4 stand for?</li><li>How many spools of ten does it take to fill one case of a hundred?</li><li>The crew has 2 cases, 5 spools, and 7 loose ribbons. What number is that?</li></ol>`,key:["The 3 stands for 3 hundreds, which is 300. The 4 stands for 4 tens, which is 40","10 spools. A hundred is the same as ten tens","257"]},4:{id:"L4",lv:true,title:"Level Up: The Setup Crew",std:["RF.2.4"],needs:["RF.1.4"],n:66,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${CREW}</p>`,key:["66 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why does the card have to sit beside the right thing? (a card in the wrong place sends people to the wrong table)"]},5:{id:"L5",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${ROSA}</p><ol class="qlist"><li>Why could Rosa not hang the chain by herself?</li><li>How did Omar solve the problem?</li></ol>`,key:["The chain kept slipping off the hook at the far end, and she could not reach it and hold the bottom at the same time","He brought a roll of tape, climbed two steps on the ladder, and taped the chain tight while Rosa held the bottom"]},6:{id:"L6",lv:true,title:"Level Up: Add It Both Ways",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:3,dir:"Solve each one on your paper. Show your work and hold it up.",html:()=>`<ol class="qlist"><li>48 + 35</li><li>72 - 26</li><li>64 + 29</li></ol>`,key:["83 (48 + 35 = 83)","46 (72 - 26 = 46)","93 (64 + 29 = 93)"]},8:{id:"L8",lv:true,title:"Level Up: Use a Ruler",std:["2.MD.A.1"],needs:["1.MD.A.2"],n:3,dir:"Look at the ruler. Answer out loud.",html:()=>`<div class="figure">${F.ruler({length:6,unit:"inches",item:4,itemLabel:"ribbon"})}</div><ol class="qlist"><li>How long is the ribbon?</li><li>Which end of the ruler does the ribbon start at?</li><li>Name a tool you would use to measure something much longer, like the whole yard.</li></ol>`,key:["4 inches","The 0 end, the left end. Measuring has to start at 0, not at the 1","A measuring tape, a yardstick, or a meter stick"]},9:{id:"L9",lv:true,title:"Level Up: Five Minutes at a Time",std:["2.MD.C.7"],needs:["1.MD.B.3"],n:3,dir:"Look at the clocks. Say each time out loud.",html:()=>`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center"><div>${F.clock(3,10,200)}<p class="fig-label">Clock E</p></div><div>${F.clock(7,45,200)}<p class="fig-label">Clock F</p></div></div><ol class="qlist"><li>What time is Clock E?</li><li>What time is Clock F?</li><li>The show starts in the evening at that second time. Is it a.m. or p.m.?</li></ol>`,key:["3:10. The minute hand is on the 2, and each number mark is five minutes","7:45, or quarter to eight. The minute hand is on the 9, which is 45 minutes","p.m. Evening is after noon"]},10:{id:"L10",lv:true,title:"Level Up: Prove It",std:["RI.2.1"],needs:["RI.1.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.5rem">${HORN_TEXT}</p><ol class="qlist"><li>How do you know the sound does not come out of the end you blow into? Read the part that shows it.</li><li>How do you know the length of a horn changes the sound? Read the part that shows it.</li></ol>`,key:["Says the wide end pushes the sound out toward the crowd, and reads the line about the wide end at the other end of the cone","Reads the line that a longer horn makes a lower sound, and may add the line about the big horns in a band sounding deep"]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RF.1.4","RL.2.1","RI.2.1","RF.2.4","RF.1.3","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","One reason is ____.","It would be ____.","That is why I would pick it."],story:["On the last day of ____, I ____.","First, ____.","Then, ____.","It felt ____."],facts:["____ is ____.","One thing about it is ____.","It also ____.","That is ____."]};const SENTSET={"W.1.1":"opinion","W.1.2":"facts","W.1.3":"story","W.1.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].wk;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}function tpsClockHtml(){return F.row([F.clock(3,0,170),"3:00, three o'clock"],[F.clock(7,30,170),"7:30, half past seven"])+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["1.NBT.B.2"],msg:"The 120 chart lays the tens out in columns, so reading the tens and ones off it is supported, not independent."},{t:"chart",std:["1.NBT.C.4","1.NBT.C.6"],msg:"On the 120 chart a student can hop down a column to add or take away a ten. Note whether the answer came from the chart or from knowing the tens."},{t:"tf",std:["1.NBT.B.2"],msg:"Ten frames show the bundles of ten for the student. Note it if the tens and ones were read off the frames rather than said from the number."},{t:"nl",std:["1.MD.A.2","2.MD.A.1"],msg:"The number line is already marked in even units, which is half of what measuring asks for. Note that the length was read off a scale you supplied."},{t:"nl",std:["1.MD.B.3"],msg:"If the number line was used to count minutes, note it. Telling time on the clock face is what this stop is checking."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.3","W.1.8","W.1.2"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart prints every numeral in order, so counting past 100 or writing a numeral off the chart is supported, not independent."},{t:"chart",std:["1.OA.C.5"],msg:"Hopping along the 120 chart does the counting on for the student. Note that the count was done on a printed scale."},{t:"nl",std:["1.OA.C.5"],msg:"The number line is already marked, so counting on or back along it is supported. Note it."},{t:"nl",std:["1.OA.A.1","1.OA.B.3"],msg:"If the number line was used to work out the word problem or the strategy, note that the answer came from counting along a scale rather than from the strategy itself."},{t:"tf",std:["1.OA.A.1","1.OA.B.3"],msg:"Ten frames show a ten already made. If the making a ten strategy came off the frames, note who filled them."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
